//! Transcript contract tests: what vx-rs actually produces for known audio.
//!
//! The unit tests in `src/main.rs` cover buffering and the hallucination filter, but
//! nothing pinned the *output* — a change to chunking, prompt, or sampling could
//! silently degrade every transcript and still ship green. These tests run the real
//! binary against the committed fixtures in `fixtures/audio/` and compare the result
//! to `fixtures/audio/goldens.json` (required keywords + a word-error-rate ceiling).
//!
//! Fixtures are macOS TTS clips regenerated by `Scripts/make-fixtures.sh`; re-key the
//! goldens afterwards with:
//!
//!   VX_UPDATE_GOLDENS=1 VX_REQUIRE_MODEL=1 cargo test --test transcript_contract
//!
//! Without a model these tests skip; `VX_REQUIRE_MODEL=1` turns that into a failure so
//! CI cannot pass vacuously. See `tests/common/mod.rs` for all env vars.

mod common;

use common::{assert_golden, fixture, model_guard, normalize, read_wav_f32, run_file, run_stream,
             stdout_text, wer};

/// The engine whose goldens these tests assert against.
///
/// To add a second engine (e.g. Parakeet): give each fixture a sibling key in
/// goldens.json (`"parakeet-v2": { … }`), then replace this constant with a loop over
/// the engine ids, resolving the binary and its arguments per engine in `common`.
/// The golden lookup, keyword check, and WER comparison are already engine-parameterized.
const ENGINE: &str = "whisper-tiny.en";

/// Transcribes a fixture through `stream` mode and asserts its golden.
fn assert_stream_fixture(name: &str) {
    require_model!(model);
    let _guard = model_guard();

    let samples = read_wav_f32(&fixture(name));
    let output = run_stream(&model, &samples);
    let transcript = stdout_text(&output);
    assert_golden(name, ENGINE, &transcript);
}

// ── stream mode: one test per fixture ────────────────────────────────────────

#[test]
fn stream_short_phrase() {
    assert_stream_fixture("short-phrase");
}

