// ── cross-mode and structural contracts ──────────────────────────────────────

/// `file` and `stream` share the same chunking and inference path, differing only in
/// how audio arrives. They must therefore agree closely; divergence means one path
/// mangled the samples (wrong scaling, dropped bytes, a stray resample).
#[test]
fn stream_and_file_agree_on_short_phrase() {
    require_model!(model);
    let _guard = model_guard();

    let wav = fixture("short-phrase");
    let from_file = stdout_text(&run_file(&model, &wav));
    let from_stream = stdout_text(&run_stream(&model, &read_wav_f32(&wav)));

    let rate = wer(&normalize(&from_file), &normalize(&from_stream));
    assert!(
        rate <= 0.1,
        "file and stream modes disagree (WER {rate:.3} > 0.100)\n\
         file:   {from_file:?}\n\
         stream: {from_stream:?}"
    );
}

/// Audio longer than the 30 s Whisper context is split into chunks and the parts are
/// rejoined. This asserts nothing falls out at the seam: the 45 s lighthouse story
/// spans two chunks, so words from *both* the opening (first ~10 s, chunk 1) and the
/// closing (last ~10 s, chunk 2) must survive. A dropped chunk still yields fluent
/// text and a plausible WER, so only end-to-end keyword coverage catches it.
#[test]
fn long_45s_crosses_chunk_boundary_without_loss() {
    require_model!(model);
    let _guard = model_guard();

    let transcript = stdout_text(&run_stream(&model, &read_wav_f32(&fixture("long-45s"))));
    let words = normalize(&transcript);
    let has = |w: &str| words.iter().any(|x| x == w);

    // Opening: "The lighthouse keeper climbed the spiral stairs every evening at dusk.
    //           He carried a brass lantern, a thermos of tea, and a worn logbook."
    let opening = ["lighthouse", "keeper", "spiral", "stairs", "dusk", "brass", "lantern"];
    // Closing: "After forty years he knew every stone of the tower… When the automatic
    //           lamp finally arrived, he stayed on for one more season, just to be sure."
    let closing = ["forty", "years", "tower", "automatic", "lamp", "season"];

    assert!(
        opening.iter().any(|w| has(w)),
        "transcript has no words from the first chunk of a 45 s recording — the opening \
         audio was dropped.\nlooked for {opening:?}\ntranscript: {transcript:?}"
    );
    assert!(
        closing.iter().any(|w| has(w)),
        "transcript has no words from the final chunk of a 45 s recording — audio past \
         the 30 s boundary was dropped.\nlooked for {closing:?}\ntranscript: {transcript:?}"
    );
}

/// The Swift side pastes stdout verbatim, so `stream` must emit at most one line
/// however many chunks it transcribed. long-60s spans three chunks; if the join ever
/// became a per-chunk `println!`, this catches it before a multi-line paste ships.
#[test]
fn stream_emits_at_most_one_line() {
    require_model!(model);
    let _guard = model_guard();

    let output = run_stream(&model, &read_wav_f32(&fixture("long-60s")));
    assert!(output.status.success(), "vx-rs stream exited with {:?}", output.status);

    let stdout = String::from_utf8_lossy(&output.stdout);
    let newlines = stdout.trim_end_matches('\n').matches('\n').count();
    assert_eq!(
        newlines, 0,
        "stream mode must emit at most one line, got {} lines:\n{stdout}",
        newlines + 1
    );
}
